head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.pBzProcsNo = "";
scwin.visuShrsLabelNm = "주식";
scwin.vIsuDtlRowPosition = "";
scwin.cal = true;
scwin.chkPrtdepoCond = true;
scwin.formCd = "";
scwin.vStkOptComNm = "";
scwin.market = "";   // 시장 구분 (onpageload 에서 세션으로 채움)
/************************************************************************************
 * ID           :	ULDSTF92050
 * File         :	ULDSTF92050.xml
 * Name         :	주권 주식발행관리(추가상장)
 * Author       :	배성우
 * Description  :
 * Create Date  :	2026-07-31
 ************************************************************************************/

// 유가보호예수 추가
// 스톡옵션 의무보유 추가

scwin.BTN_MAP = {
    "save": "btn_save",
    "modify": "btn_update",
    "delete": "btn_delete",
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {

        // 초기화함수

        await scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92050.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.market = $c.session.getUserInfo("market");

    // let parentWin = scwin.getProvider();
    let parentWin = $c.data.getParameter();

    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vSecugrpID = parentWin.fr_SecuGrpId;
    scwin.vPageTYp = parentWin.vPageTYp;
    scwin.vSpotIsuTrdMktTpCd = parentWin.vSpotIsuTrdMktTpCd;
    ibx_isurCd.setValue(parentWin.isurCd);
    ibx_comNm.setValue(parentWin.comNm);
    scwin.gAcptNo = parentWin.gAcptNo;
    scwin.gAcptSeq = (parentWin.gAcptSeq === "" ? 0 : parentWin.gAcptSeq);

    // 상장수수료를 위한 접수번호
    scwin.gAcptNoListFee = parentWin.gAcptNoListFee;
    scwin.setObjectState();

    await scwin.searchCode();
    scwin.setPanelPREFSTK(false); // 일단 false;
    scwin.setPREFSTKItem(false); // 일단 false;

    cal_approvDd.setValue($c.date.getServerDateTime());
    dlt_listMethdTpCdCodRes_sub.removeAll();
    if (scwin.vBzProcsNo !== "") {
        // sbx_listMethdTpCd.CBData = "1^신주상장,2^추가상장,3^변경상장,4^신규상장,5^재상장";
        dlt_listMethdTpCdCodRes_sub.setJSON(dlt_listMethdTpCdCodRes.getAllJSON());
        await scwin.readSync();
    } else {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        if ($c.util.isNotEmpty(scwin.gAcptNo)) {
            await scwin.extrReadSync();
            // scwin.setHeader('N');
        } else {
            // scwin.setHeader('Y');
        }

        // let vListMthTpCd;
        if (scwin.vPageTYp === '1') {
            // vListMthTpCd = "2^추가상장";
            // sbx_listMethdTpCd.CBData = vListMthTpCd;
            dlt_listMethdTpCdCodRes_sub.setRowData(0, ["추가상장", "2"]);
            // sbx_listMethdTpCd.Index = 1;
            sbx_listMethdTpCd.setSelectedIndex(1);
            await scwin.nprefstkReadSync(ibx_isuCd.getValue());
        } else if (scwin.vPageTYp === '2') {
            // vListMthTpCd = "3^변경상장";
            // sbx_listMethdTpCd.CBData = vListMthTpCd;
            dlt_listMethdTpCdCodRes_sub.setRowData(0, ["변경상장", "3"]);
            sbx_listMethdTpCd.setSelectedIndex(1);
        }
    }
    scwin.setTabPanel();

    // TODO: TEST - 저장 테스트
    // ibx_isuCd.setValue("KR7043910009");
    // ibx_isuSrtCd.setValue("A043910");
    // ibx_isuEngSymbl.setValue("");
    // ibx_isuKorNm.setValue("자연과환경보통주");
    // ibx_isuKorAbbrv.setValue("자연과환경");
    // ibx_isuEngNm.setValue("NatureandEnvironment");
    // ibx_isuEngAbbrv.setValue("NNE");

    // buttonSet.setButtonDepCd(dts_ByCorpDepCd, ibx_isurCd.getValue(), js_dep_cd);
    if (sbx_stkcertKindCd.getValue() !== "KDR" && sbx_stkcertKindCd.getValue().substring(0, 1) === "K") {
        scwin.setNPARVALSTK(true);
    } else {
        scwin.setNPARVALSTK(false);
    }
    // 주식발행사유가 스톡옵션행사(117)(유), 주식매수선택권행사(614)(코) 인경우 주식매수선택권 의무보유 관리 팝업창 호출
    // let parentSrc = parentWin.menuInfo.src;
    let parentSrc = $c.win.getParent().scwin.vScrenID;
    if ((parentSrc === "ULDSTF05200.xml" || parentSrc === "ULDSTF05255.xml") && (scwin.vSecugrpID === "ST" || scwin.vSecugrpID === "DR" || scwin.vSecugrpID === "FS") &&
        // if ((parentSrc.indexOf("ULDSTF05200.xml") > 0 || parentSrc.indexOf("ULDSTF05255.xml") > 0) && (scwin.vSecugrpID === "ST" || scwin.vSecugrpID === "DR" || scwin.vSecugrpID === "FS") &&
        (sbx_stkIsuRsnCd.getValue() === "117" || sbx_stkIsuRsnCd.getValue() === "614")) {
        scwin.vStkOptIsurCd = ibx_isurCd.getValue();
        scwin.vStkOptComNm = ibx_comNm.getValue();

        const opts = {
            id: "ULDSTF40003",
            popupName: "주식매수선택권 의무보유 관리",
            width: 900,
            height: 1000,
            frameModal: "top",
            type: "pageFramePopup",
        };
        const res = await $c.win.openPopup("/ui/lst/lstmgt/ULDSTF40003.xml", opts);
    }
}

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_isuCd_onclick
 * @description 종목코드 선택 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_isuCd_onclick = async function () {
    try {
        let vListMthTpCd = sbx_listMethdTpCd.getValue();
        if (sbx_listMethdTpCd.getValue() === "") {
            $c.win.alert("먼저 [상장방식]을 선택하세요.");
            sbx_listMethdTpCd.focus();
            return;
        }
        // scwin.fn_GetPar = fn_GetParIsuCd;
        // scwin.fn_SetPar = fn_SetParIsuCd;

        let res;
        const data = {
            secugrpId: scwin.vSecugrpID,
            isurCd: ibx_isurCd.getValue(), // 코드값을 포함할 컨트롤
        }
        if (vListMthTpCd === $c.lc.getGlbValue("LIST_METHD_TP_CD_1")) {
            // 신주상장
            res = await $c.lc.popFindNewIsuOfIsur(scwin.vSecugrpID, ibx_isurCd.getValue());
        } else if (vListMthTpCd === $c.lc.getGlbValue("LIST_METHD_TP_CD_2") || vListMthTpCd === $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
            // 추가($c.lc.getGlbValue("LIST_METHD_TP_CD_2")),변경상장($c.lc.getGlbValue("LIST_METHD_TP_CD_3"))
            res = await $c.lc.popFindIsuOfIsur(data);
        }

        // let dbClickYn =  arrPar[0].DBCLICKYN;
        if (res.isuCd) {
            ibx_isuCd.setValue(res.isuCd);
            ibx_isuKorNm.setValue(res.isuKorNm);
            ibx_isuKorAbbrv.setValue(res.isuKorAbbrv);
            ibx_isuEngNm.setValue(res.isuEngNm);
            ibx_isuEngAbbrv.setValue(res.isuEngAbbrv);
            ibx_isuSrtCd.setValue(res.isuSrtCd);
            ibx_isuEngSymbl.setValue(res.isuEngSymbl);
            sbx_currIsoCd.setValue(res.currIsoCd);

            if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
                sbx_stkcertKindCd.setValue("KDR"); // 주식의종류코드를 셋팅
            } else if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_FS")) {
                sbx_stkcertKindCd.setValue("000"); // 주식의종류코드를 셋팅
            } else {
                sbx_stkcertKindCd.setValue(ibx_isuCd.getValue().substring(8, 11)); // 주식의종류코드를 셋팅
            }

            scwin.setPREFSTKEvent();
            await scwin.nprefstkReadSync(ibx_isuCd.getValue());
            await scwin.bfReadSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92050.btn_isuCd_onclick" });
    }
};

/**
 * @method
