 */
scwin.cbx_indefinpdYn02_onclick = function () {
    try {
        if (cbx_nparvalstkYn.checked) {
            ibx_prefstkContinDeadlineYys02.setValue('');
            ibx_prefstkContinDeadlineMm02.setValue('');
            ibx_prefstkContinDeadlineDys02.setValue('');
            ibx_prefstkEndDd02.setValue('');
        }
    } catch (ex) {
