/**
 * @method
 * @name btn_isuEngSymbl_onclick
 * @description 중복체크 버튼 — 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_isuEngSymbl_onclick = async function () {
    try {
        if (ibx_isuEngSymbl.getValue() === "") {
            await $c.win.alert("[영문종목심볼]을 입력하세요.");
            ibx_isuEngSymbl.focus();
            return false;
        } else {
            if (await $c.lc.engSymblCheck(ibx_isuEngSymbl.getValue())) {
                await $c.lc.chkCorpSymblDoubleInput(ibx_isuEngSymbl.getValue(), ibx_isurCd.getValue(), "dts_Symbl");
                if (!$c.util.isEmpty($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"))) {
                    $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
                }
            } else {
                ibx_isuEngSymbl.focus();
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92050.btn_isuEngSymbl_onclick" });
    }
};

/**
 * @method
