/**
 * @method
 * @name cbx_newstkRelLawstYn_onviewchange
 * @description 신주발행의 효력등과 관련한 소송제기여부 체크박스 클릭
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cbx_newstkRelLawstYn_onviewchange = function (info) {
    try {
            if (info.checked) {
            cal_filelawstDd.setReadOnly(false);
            cal_filelawstDd.ReadOnlyBackgroundColor = '#ffffff';
        } else {
            cal_filelawstDd.setReadOnly(true);
            cal_filelawstDd.ReadOnlyBackgroundColor = '#b9d4f7';
            cal_filelawstDd.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92050.cbx_newstkRelLawstYn_onviewchange" });
    }
};

