/**
 * @method
 * @name dts_IsuDtl_OnLoadCompleted
 * @description dts_IsuDtl 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuDtl_OnLoadCompleted = function (rowcount) {
    try {
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            let vListMthTpCd = dma_selectListRes.get("LIST_METHD_TP_CD");
            if (vListMthTpCd === $c.lc.getGlbValue("LIST_METHD_TP_CD_1") || vListMthTpCd === $c.lc.getGlbValue("LIST_METHD_TP_CD_2")) {
                // 주식발행사유로 체크하지말고 건수로 하자..
                if (dts_IsuDtl.getRowCount() === 0) {
                    dts_IsuDtl.insertRow();
                    dts_IsuDtl.setCellData(1, "ISU_RND", dma_selectListRes.get("ISU_RND"));
                    dts_IsuDtl.setCellData(1, "ISU_PRC", dma_selectListRes.get("ISU_PRC"));
                    dts_IsuDtl.setCellData(1, "ISU_SHRS", dma_selectListRes.get("ISU_SHRS"));
                    dts_IsuDtl.setCellData(1, "isuDd", dma_selectListRes.get("isuDd"));
                    dts_IsuDtl.setCellData(1, "PER1STK_CAP", dma_selectListRes.get("PER1STK_CAP"));
                } else {
                    dts_IsuDtl.setBroadcast(false);
                    for (j = 1; j <= dts_IsuDtl.getRowCount(); j++) {
                        dts_IsuDtl.setCellData(j, "ISU_RND", dma_selectListRes.get("ISU_RND"));
                    }
                    dts_IsuDtl.setBroadcast(true, true);
                }

                /*
                let vRsnCd = getObjectValue(sbx_stkIsuRsnCd);
                let gDtl = 'Y';
                $c.win.alert('[vRsnCd]'+vRsnCd);
                if (vRsnCd === '612' ||
                    vRsnCd === '613' ||
                    vRsnCd === '614' ||
                    vRsnCd === '617' ||
                    vRsnCd === '618' ||
                    vRsnCd === '619' ||
                    vRsnCd === '620' ||
                    vRsnCd === '621' ||
                    vRsnCd === '622' ||
                    vRsnCd === '623' ||
                    vRsnCd === '624'  ) {
                    gDtl = 'N';
                }
                 */
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92050.dts_IsuDtl_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name sbx_stkIsuRsnCd_onselchange
 * @description sbx_stkIsuRsnCd 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_stkIsuRsnCd_onselchange = function () {
    try {
        if (!btn_recvIsuDel.getDisabled()) {
            if (scwin.market === '1' && scwin.vPageTYp === "2" && sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
                // 유가, 변경상장
                if (sbx_stkIsuRsnCd.getValue() !== "" &&
                    sbx_stkIsuRsnCd.getValue() !== "170" &&
                    sbx_stkIsuRsnCd.getValue() !== "171" &&
                    sbx_stkIsuRsnCd.getValue() !== "172" &&
                    sbx_stkIsuRsnCd.getValue() !== "173" &&
                    sbx_stkIsuRsnCd.getValue() !== "174" &&
                    sbx_stkIsuRsnCd.getValue() !== "177" &&
                    sbx_stkIsuRsnCd.getValue() !== "118" &&
                    sbx_stkIsuRsnCd.getValue() !== "160" &&
                    sbx_stkIsuRsnCd.getValue() !== "161" &&
                    sbx_stkIsuRsnCd.getValue() !== "180" &&
                    sbx_stkIsuRsnCd.getValue() !== "162" &&
                    sbx_stkIsuRsnCd.getValue() !== "163" &&
                    sbx_stkIsuRsnCd.getValue() !== "175" &&
                    sbx_stkIsuRsnCd.getValue() !== "176") {
                    // confirm: 반환값을 동기 boolean 으로 소비하는 위치 — $c.win.confirm 은 Promise 라 1:1 치환 불가(컨벤션 예외, 전환 시 async 재설계 필요)
                    if (!confirm("변경상장에서 안내문 형식이 정의되지 않은 주식 발행사유 입니다. \n그래도 선택한 주식발행사유를 입력하시겠습니까?")) {
                        sbx_stkIsuRsnCd.setValue('');
                        return;
                    }
                }
            }
        }
        scwin.setTabPanel(); // 625:우선주의 보통주전환  추가(2017.07.14)

        scwin.calcuAccIsuShrs();
        scwin.calcuAccIsuCap();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92050.sbx_stkIsuRsnCd_onselchange" });
    }
};

/**
 * @method
 * @name sbx_listMethdTpCd_onselchange
 * @description sbx_listMethdTpCd 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_listMethdTpCd_onselchange = function () {
    try {
        if (sbx_listMethdTpCd.getValue() === "1") {
            let vListMthTpCd = sbx_listMethdTpCd.getValue();
            if (scwin.vPageTYp === '1') {
                if (vListMthTpCd !== $c.lc.getGlbValue("LIST_METHD_TP_CD_2")) {
                    $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
                    sbx_listMethdTpCd.setValue('2');
                    sbx_listMethdTpCd.focus();
                    return false;
                }
            } else if (scwin.vPageTYp === '2') {
                if (vListMthTpCd !== $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
                    $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
                    sbx_listMethdTpCd.setValue('3');
                    sbx_listMethdTpCd.focus();
                    return false;
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92050.sbx_listMethdTpCd_onselchange" });
    }
};

