/**
 * @method
 * @name button_1_onclick
 * @description 종류주식 버튼 — 「종류주식」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.button_1_onclick = async function () {
    try {
        const sbmOptions3 = {
            id : "sbm_dts_KindStkBzProcsNo",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_KindStkBzProcsNo=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // //ShowWin(dts_PRTDEPO);
        // scwin.pBzProcsNo = dts_KindStkBzProcsNo.getCellData(1, "bzProcsNo");
        // // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("DLG_KIND_STK_PREEXAM", "/kindstk/ULDSTF05106_read.xml", $c.lc.getSecuGrpNm(scwin.vSecugrpID) + " 종류주식 상세", 100, 100, 1090, 700, "window");

        let reqMap = {
            isurCd: txb_isurCd.getValue(),
            stkcertKindCd: sbx_STKCERT_KIND_CD.getValue()
        };
        const sbmOptions = {
            id: "sbm_select_acptno",
            action: "/api/listing/lstproc/stock/chglisting/select-apfm-by-acptno",
            method: "get",
            target: "dma_KindStkBzProcsNo=body",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

        if (res.responseJSON.success) {
            scwin.pBzProcsNo = dma_KindStkBzProcsNo.get("bzProcsNo");

            let url = "/ui/lstproc/ULDSTF05106_read.xml";
            let popTitle = $c.lc.getSecuGrpNm(scwin.vSecugrpID) + " 종류주식 상세";

            const opts = {
                id: "ULDSTF05106_read",
                popupName: popTitle,
                width: 1135,
                height: 840,
                frameModal: "top",
            };

            await $c.win.openPopup(url, opts);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92050.button_1_onclick" });
    }
};

