/**
 * @method
 * @name readSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function () {
    const sbmOptions3 = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dma_selectListReq.set("bzProcsNo", scwin.vBzProcsNo); // 업무처리번호
    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/lstproc/stock/issuance-manage/select-list",
        method: "get",
        ref: "dma_selectListReq",
        target: "dma_selectListRes=body.issInfo",
        isProcessMsg: false
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler scwin.sbm_selectList_submitdone 미정의)

    let vCurDate = $c.date.getServerDateTime();
    if (scwin.vBzProcsNo === "") {
        // scwin.setInsertStatus();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        scwin.initForm('I');
    } else {
        scwin.initForm('X');
        if (vCurDate <= cal_listDd.getValue()) {
            // scwin.setUpdateStatus();
            $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
        } else {
            if (dma_selectListRes.get("disclsYn") === 'Y') {
                // scwin.setErrorStatus(); //disable 시킨다.
                $c.util.setButtonState("grpBtnBox", "error", scwin.BTN_MAP);

            } else {
                // scwin.setUpdateStatus();
                $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
            }
        }
    }
    if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
        // btn_recvIsuDel.src = "../img/btn_RcvdocDel.gif";
        btn_recvIsuDel.setDisabled(false);
    } else {
        // btn_recvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_recvIsuDel.setDisabled(true);
    }
    scwin.setTabPanel();

    // AS-IS 뒷 로직
    if (dma_selectListRes.get("prefstkTpCd") === '2') {
        // cbx_prefstkTpCd.setValue(1); //신형우선주 여부
        scwin.setPREFSTKItem(true);
        scwin.setPanelPREFSTK(true);
    } else {
        scwin.setPREFSTKEvent();
    }
    if (dma_selectListRes.get("nparvalstkYn") === 'Y') {
        cbx_nparvalstkYn.setValue(1);
    }
    scwin.setNPARVALSTKYNEvent();

    // AS-IS 변경후 상장주식수, 변경 상장자본금 뒤에 글자 붙여주는 것
    // TO-BE 글자 붙이는 걸 삭제한 것 같음
    // txb_CURR_ISO_NM_1.setValue("(" + dma_selectListRes.get("CURR_ISO_CD") + ")");
    // txb_CURR_ISO_NM_2.setValue("(" + dma_selectListRes.get("CURR_ISO_CD") + ")");
    // txb_CURR_ISO_NM_3.setValue("(" + dma_selectListRes.get("CURR_ISO_CD") + ")");
    // txb_CURR_ISO_NM_4.setValue("(" + dma_selectListRes.get("CURR_ISO_CD") + ")");

    scwin.setNprefCheckBox(dma_selectListRes);
    scwin.setCheckboxData(cbx_newstkRelLawstYn, dma_selectListRes.get("newstkRelLawstYn"));
    scwin.setCheckboxData(cbx_backlistYn, dma_selectListRes.get("backlistYn"));
    const sbmOptions4 = {
        id : "sbm_dts_IsuDtl",
        action : "/Listing.do",
        ref : "",
        target : "dts_IsuDtl=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 보호예수로 추가
    // await scwin.prtdepoReadSync();
};

