scwin.recvtIsuDel = async function () {
    scwin.TR_JOB = 'D';
    if (!await window.confirm($c.data.getMessage('com_crud_0198', "신청종목삭제"))) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
    if (String(scwin.vBzProcsNo).length !== 14) {
        $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
    } else {
        dma_selectListRes.set("bzProcsNo", scwin.vBzProcsNo);
        dma_selectListRes.set("isurCd", ibx_isurCd.getValue());
        // trs_Save.Action = $c.lc.encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=saveIsuIssChgList");
