        // trs_Save.Post();

        const reqMap = {
            bzProcsNo: scwin.vBzProcsNo,
            isurCd: ibx_isurCd.getValue(),
            acptNo: scwin.gAcptNo,
            byacptnoSeq: scwin.gAcptSeq,
            listBzTpCd: scwin.getListBzTpCd()
        };
        const sbmOptions = {
            id: "sbm_remove",
            action: "/api/listing/lstproc/stock/issuance-manage-applied-isu/remove",
            method: "post",
            ref: "dma_selectListRes",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

        if (res.responseJSON.success) {
            // scwin.fn_parentRefresh(); // 목록 다시 조회

            $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
            await $c.win.closePopup();
        } else {
            $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
            // $c.stf.alert_error(trs_Save);
        }
    }
};

