/**
 * @method
 * @name print
 * @description 인쇄
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    let vReportCd = sbx_reportCd.getValue(); // 1^인쇄,2^보호예수인쇄,3^통합인쇄
    let vBzProcsKey = scwin.vBzProcsNo;

    if (vReportCd === "1") {
        let isuRsnCd = sbx_stkIsuRsnCd.getValue();
        if (isuRsnCd === '643') {
            // 상호변경(코)
            scwin.print11(vBzProcsKey);
        } else {
            scwin.print12(vBzProcsKey, 'N');
        }
    } else if (vReportCd === "2") {
        scwin.print2(vBzProcsKey); // 우리기술...

    } else if (vReportCd === "3") {
        const sbmOptions3 = {
            id : "sbm_dts_Report_4",
            action : "/Listing.do",
            ref : "",
            target : "dts_Report_4=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const reqMap = {
            isurCd: ibx_isurCd.getValue(),
            listDd: cal_listDd.getValue(),
            stkIsuRsnCd: sbx_stkIsuRsnCd.getValue(),
        };
        const sbmOptions = {
            id: "sbm_select",
            action: "/api/listing/lstproc/stock/issuance-manage/print-key/select-list",
            method: "get",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
        if (res.responseJSON.success) {
            let pValue = "";
            let k = 0;
            for (let i = 0; i <= res.responseJSON.body.length; i++) {
                if (k === 0) {
                    pValue = res.responseJSON.body[i].bzProcsNo;
                } else {
                    pValue = pValue + "," + res.responseJSON.body[i].bzProcsNo;
                }
                k++;
            }
            vBzProcsKey = pValue;
            scwin.print12(vBzProcsKey, 'Y');
        }
    }
};

