 * @hidden N
 */
scwin.setPREFSTKEvent = function () {
    if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_ST")) {
        if (sbx_stkcertKindCd.getValue() === '000' || sbx_stkcertKindCd.getValue().substring(0, 1) === 'K') {
            scwin.setPREFSTKItem(false);
