/**
 * @method
 * @name setCheckboxData
 * @description 체크박스 데이터세팅
 * @param {Object} obj 객체
 * @param {String|Number} val 값
 * @returns {void}
 * @hidden N
 */
scwin.setCheckboxData = function (obj, val) {
    if (val === 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};

/**
 * @method
 * @name getCheckboxData
 * @description checkBox 데이터 세팅
 * @param {Object} obj 객체
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getCheckboxData = function (obj) {
    if (obj.getValue() === "Y") {
        return 'Y';
    } else {
        return 'N';
    }
};

/**
 * @method
 * @name setNprefCheckBox
 * @description 만료일 옆 여부 체크박스들
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setNprefCheckBox = function (dtsObj) {
    scwin.setCheckboxData(cbx_indefinpdYn, dtsObj.get("indefinpdYn")); // 무기한여부
    scwin.setCheckboxData(cbx_partctpYn, dtsObj.get("partctpYn"));
    scwin.setCheckboxData(cbx_acctpYn, dtsObj.get("acctpYn"));
    scwin.setCheckboxData(cbx_ndivtmVoterghtYn, dtsObj.get("ndivtmVoterghtYn"));
};

/**
 * @method
 * @name checkForm
 * @description validation 확인
 * @returns {Promise<Boolean>} 판정 결과
 * @hidden N
 */
scwin.checkForm = async function () {
    let vCurDate = $c.date.getServerDateTime();
    let fields = {}; // validate 체크목록
    const options = {
        validateType: "alert",
        checkType: "single",
        focus: true,
        fields: fields,
    };

    fields["ibx_isurCd"] = { required: true, name: "회사코드" };
    fields["sbx_listMethdTpCd"] = { required: true, name: "상장방식" };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    let vListMthTpCd = sbx_listMethdTpCd.getValue();
    if (scwin.vPageTYp === '1') {
        if (vListMthTpCd !== $c.lc.getGlbValue("LIST_METHD_TP_CD_2")) {
            await $c.win.alert($c.data.getMessage("com_select_0075"));
            sbx_listMethdTpCd.focus();
            return false;
        }
    } else if (scwin.vPageTYp === '2') {
        if (vListMthTpCd !== $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
            await $c.win.alert($c.data.getMessage("com_select_0076"));
            sbx_listMethdTpCd.focus();
            return false;
        }
    }

    fields["ibx_isuCd"] = { required: true, name: "종목" };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_1")) {
        let dbchkCnt = -1;
        dbchkCnt = scwin.checkDoubleListed();
        if (dbchkCnt > 0) {
            $c.win.alert($c.data.getMessage("com_select_0077"));
            return false;
        }

        fields["ibx_isuSrtCd"] = { required: true, name: "종목단축코드" };
        fields["ibx_isuKorNm"] = { required: true, name: "한글종목명" };
        fields["ibx_isuKorAbbrv"] = { required: true, name: "한글종목약명" };
        fields["ibx_isuEngNm"] = { required: true, name: "영문종목명" };
        fields["ibx_isuEngAbbrv"] = { required: true, name: "영문종목약명" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

        if (scwin.vSpotIsuTrdMktTpCd === "1") {

            fields["ibx_isuEngSymbl"] = { required: true, name: "영문종목심볼" };
            if (!await $c.validate.validateDataCollect(grp_table, options)) {
                return false;
            }

            if ($c.lc.engSymblCheck(ibx_isuEngSymbl.getValue())) {
                if (!$c.lc.chkCorpSymblDoubleInput(ibx_isuEngSymbl.getValue(), ibx_isurCd.getValue(), "dts_Symbl")) {
                    $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
                    return false;
                }
            } else {
                ibx_isuEngSymbl.focus();
                return false;
            }
        }
    }
    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_2")) {
        // 추가상장
        if (sbx_stkIsuRsnCd.getValue() === "609" || sbx_stkIsuRsnCd.getValue() === "626" || sbx_stkIsuRsnCd.getValue() === "627" ||
            sbx_stkIsuRsnCd.getValue() === "640" || sbx_stkIsuRsnCd.getValue() === "641" || sbx_stkIsuRsnCd.getValue() === "643" ||
            sbx_stkIsuRsnCd.getValue() === "632" || sbx_stkIsuRsnCd.getValue() === "633" || sbx_stkIsuRsnCd.getValue() === "648" ||
            sbx_stkIsuRsnCd.getValue() === "649") {
            await $c.win.alert("[추가상장]에 해당하는 주식발행사유가 아닙니다. 주식발행사유를 확인하시기 바랍니다.");
            sbx_stkIsuRsnCd.focus();
            return;
        }
    }
    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
        // 변경상장
        if (sbx_stkIsuRsnCd.getValue() === "602" || sbx_stkIsuRsnCd.getValue() === "644" || sbx_stkIsuRsnCd.getValue() === "608" ||
            sbx_stkIsuRsnCd.getValue() === "611" || sbx_stkIsuRsnCd.getValue() === "614" || sbx_stkIsuRsnCd.getValue() === "617" ||
            sbx_stkIsuRsnCd.getValue() === "618" || sbx_stkIsuRsnCd.getValue() === "619" || sbx_stkIsuRsnCd.getValue() === "620" ||
            sbx_stkIsuRsnCd.getValue() === "621" || sbx_stkIsuRsnCd.getValue() === "622" || sbx_stkIsuRsnCd.getValue() === "623" ||
            sbx_stkIsuRsnCd.getValue() === "624" || sbx_stkIsuRsnCd.getValue() === "630" || sbx_stkIsuRsnCd.getValue() === "631" ||
            sbx_stkIsuRsnCd.getValue() === "642") {
            await $c.win.alert("[변경상장]에 해당하는 주식발행사유가 아닙니다. 주식발행사유를 확인하시기 바랍니다.");
            sbx_stkIsuRsnCd.focus();
            return;
        }
    }

    // 2009.04.07 변경상장일경우는 상장일을 입력안해도 되도록 변경함.
    if (scwin.vPageTYp === '2') {
        // 코스닥 일때만 주식발행사유 600번대
        if (sbx_stkIsuRsnCd.getValue() >= 600 && sbx_stkIsuRsnCd.getValue() !== "625") {
            // 상장일이 없으면 '-' 으로 대체
            if (cal_listDd.getValue() === "") {
                dma_selectListRes.set("LIST_DD", '-');
                await $c.win.alert("변경상장일 경우 상장일 입력을 안하시면 '-' 으로 처리됩니다.");
            }
        } else {
            fields["cal_listDd"] = { required: true, name: "상장일" };
            if (!await $c.validate.validateDataCollect(grp_table, options)) {
                return false;
            }

        }
    } else {
        fields["cal_listDd"] = { required: true, name: "상장일" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

        if (vCurDate >= cal_listDd.getValue()) {
            await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
            cal_listDd.focus();
            return false;
        }
    }
    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_3")) {
        // 20081017 코스닥이고 이익소각이면 발행일자 입력이 필수가 아니도록 변경
        // 20100514 코스닥이고 감자(유상)일 경우 발행일자와 발행회차 입력이 필수가 아니도록 변경
        // 626 : 이익소각, 609 : 감자(유상)
        // 699 : 기타 추가 20100809(강진희)
        // 650:주식소각
        // 625:우선주의 보통주전환  추가(2017.05.15)

        if (sbx_stkIsuRsnCd.getValue() === "626" || sbx_stkIsuRsnCd.getValue() === "609" || sbx_stkIsuRsnCd.getValue() === "650" || sbx_stkIsuRsnCd.getValue() === "625" ||
            sbx_stkIsuRsnCd.getValue() === "699") {

        } else {
            fields["cal_isuDd"] = { required: true, name: "발행일" };
            fields["ibx_isuRnd"] = { required: true, name: "발행회차" };
            if (!await $c.validate.validateDataCollect(grp_table, options)) {
                return false;
            }

        }
        if (sbx_stkIsuRsnCd.getValue() === "625") {
            if (!scwin.checkIsuDtlDtl(dts_IsuDtl)) return false;
        }
    }

    fields["sbx_stkcertKindCd"] = { required: true, name: "주식의종류" };
    fields["sbx_stkIsuRsnCd"] = { required: true, name: "주식발행사유" };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    let isuRsnCd = sbx_stkIsuRsnCd.getValue();
    if (isuRsnCd === '115') {
        await $c.win.alert($c.data.getMessage("com_empty_0188"));
        sbx_stkIsuRsnCd.focus();
        return false;
    }
    // 신규상장시 선택하는 발행사유들...
    if (isuRsnCd === '198') {
        await $c.win.alert($c.data.getMessage("com_empty_0189"));
        sbx_stkIsuRsnCd.focus();
        return false;
    }
    if (isuRsnCd === '180') {
        await $c.win.alert($c.data.getMessage("com_empty_0190"));
        sbx_stkIsuRsnCd.focus();
        return false;
    }
    if (isuRsnCd === '181') {
        await $c.win.alert($c.data.getMessage("com_empty_0191"));
        sbx_stkIsuRsnCd.focus();
        return false;
    }
    if (isuRsnCd === '601') {
        await $c.win.alert($c.data.getMessage("com_empty_0192"));
        sbx_stkIsuRsnCd.focus();
        return false;
    }
    if (isuRsnCd === '643' || isuRsnCd === '160') {
        let dbchkCnt = -1;
        dbchkCnt = scwin.checkComNmInput();
        if (dbchkCnt === 0) {
            await $c.win.alert("주식발행사유가 [상호변경]시에는 \r\n\r\n" + "먼저 [변경상장 > 상호변경] 탭화면에서 변경상장일을 동일일자로 상호변경내용을 입력하시기 바랍니다.");
            return false;
        }
        if (ibx_isuShrs.getValue() !== "0") {
            ibx_isuShrs.setValue(0);
            await $c.win.alert($c.data.getMessage("com_etc_0164", scwin.visuShrsLabelNm));
        }
    }

    ///*
    if (scwin.vSecugrpID !== $c.lc.getGlbValue("SECUGRP_ID_MF") && scwin.vSecugrpID !== $c.lc.getGlbValue("SECUGRP_ID_IF") && scwin.vSecugrpID !== $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        if (cbx_nparvalstkYn.getValue() !== "Y" && ibx_parval.getValue() === "0") {
            await $c.win.alert("[액면가]를 입력하세요.");
            ibx_parval.focus();
            return false;
        }
        if (cbx_nparvalstkYn.getValue() === "Y" && ibx_per1stkCap.getValue() === "") {
            await $c.win.alert("[주당자본금]을 입력하세요.");
            ibx_per1stkCap.focus();
            return false;
        }
        if (isuRsnCd !== '643' && isuRsnCd !== '160' && // 상호변경
            cbx_nparvalstkYn.getValue() !== "Y") {
            // 무액면주식 여부
            if (!await scwin.checkZeroNumber(ibx_parval, "액면가")) return false;
        }
    }
    if (isuRsnCd === '640' || isuRsnCd === '170' || // 액면병합
        isuRsnCd === '641' || isuRsnCd === '171') {
        // 액면분할

        let dbchkCnt = -1;
        dbchkCnt = scwin.checkParvalInput();
        if (cbx_nparvalstkYn.getValue() !== "Y" && dbchkCnt === 1) {
            await $c.win.alert($c.data.getMessage("com_etc_0165"));
            return false;
        }
    } else {
        if (sbx_listMethdTpCd.getValue() !== $c.lc.getGlbValue("LIST_METHD_TP_CD_1")) {
            let dbchkCnt = -1;
            dbchkCnt = scwin.checkParvalInput();
            if (cbx_nparvalstkYn.getValue() !== "Y" && dbchkCnt === 0) {
                await $c.win.alert($c.data.getMessage("com_etc_0166"));
                return false;
            }
        }
    }

    fields["ibx_isuShrs"] = { required: true, name: "증감" + scwin.visuShrsLabelNm + "수" };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    // 1: 신주상장, 2: 추가상장
    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_1") || sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_2")) {
        if (!scwin.checkIsuDtlDtl(dts_IsuDtl)) return false;
        if (scwin.vSecugrpID !== $c.lc.getGlbValue("SECUGRP_ID_DR")) {
            if (!await scwin.checkZeroNumber(ibx_isuCap, "증감 상장자본금")) return false;
        }
        if (!await scwin.checkZeroNumber(ibx_isuShrs, "'증감" + scwin.visuShrsLabelNm + "수")) return false;
    }
    if (scwin.vSecugrpID !== $c.lc.getGlbValue("SECUGRP_ID_DR")) {

        fields["ibx_isuCap"] = { required: true, name: "증감 상장자본금" };
        fields["ibx_accIsuShrs"] = { required: true, name: "변경후 상장주식수" };
        fields["ibx_accIsuCap"] = { required: true, name: "변경후 상장자본금" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

        if (ibx_accIsuShrs.getValue() === "0") {
            await $c.win.alert($c.data.getMessage("com_calc_0009"));
            ibx_accIsuShrs.focus();
            return false;

        }
        if (ibx_accIsuCap.getValue() === "0") {
            await $c.win.alert($c.data.getMessage("com_etc_0167"));
            ibx_accIsuCap.focus();
            return false;

        }
    } else {
        if (ibx_accIsuShrs.getValue() === "0") {
            await $c.win.alert($c.data.getMessage("com_etc_0168", lb_ACC_ISU_SHRS.getValue(), lb_ACC_ISU_SHRS.getValue()));
            ibx_accIsuShrs.focus();
            return false;
        }
    }

    // 699 : 기타 일 경우 배당기산일1을 체크하지 않는다. 20100809
    if (sbx_stkIsuRsnCd.getValue() === "699") {

    } else {
        fields["cal_divReckDd1"] = { required: true, name: "배당기산일1" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

    }

    // 신형우선주 여부
    if (sbx_stkcertKindCd.getValue() === "000" || sbx_stkcertKindCd.getValue() === "KDR" || sbx_stkcertKindCd.getValue().substring(0, 1) === "K") {
        if (cbx_prefstkTpCd.checked) {
            await $c.win.alert("[신형우선주여부]는 우선주일 경우에만 선택하십시요.");
            cbx_prefstkTpCd.focus();
            return false;
        }
    }
    if (cbx_prefstkTpCd.checked) {
        fields["ibx_prefstkDivRt"] = { required: true, name: "우선주배당률" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

        if (cal_prefstkEndDd.getValue() === "" && !cbx_indefinpdYn.checked) {
            await $c.win.alert("[무기한여부] 또는 [존속기한]을 선택하세요.\n\n만료일은 [존속기한]을 입력하면 자동계산됩니다.");
            ibx_prefstkContinDeadlineYys.focus();
            return false;
        }
        if (cal_prefstkEndDd.getValue() !== "" && cbx_indefinpdYn.checked) {
            await $c.win.alert("[무기한여부] 또는 [존속기한] 항목중 하나만 선택하십시오.");
            ibx_prefstkContinDeadlineYys.focus();
            return false;
        }
    }
    if (cbx_newstkRelLawstYn.checked) {
        fields["cal_filelawstDd"] = { required: true, name: "소송제기일" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }
    } else {
        if (cal_filelawstDd.getValue() !== "") {
            $c.win.alert("소송제기여부 해당시만 [소송제기일]을 입력하세요.");
            cal_filelawstDd.focus();
            return false;
        }
    }
    if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        ibx_parval.setValue('0');
        ibx_isuCap.setValue('0');
        ibx_accIsuCap.setValue('');
    }
    if (dlt_prtdepoSelectListRes.getRowCount() > 0) {
        if (!scwin.checkPRTDEPO(dlt_prtdepoSelectListRes)) return false;
    }
    if (scwin.TR_JOB === "I") {
        let cntIssDoubleInput = -1;
        cntIssDoubleInput = await scwin.checkListDdOver();
        if (cntIssDoubleInput > 0) {
            $c.win.alert($c.data.getMessage("com_date_compare_0207"));
            return false;
        }
        cntIssDoubleInput = await scwin.checkIssDoubleinput();
        if (cntIssDoubleInput > 0) {
            $c.win.alert($c.data.getMessage("com_date_compare_0208"));
            return false;
        }
    }

    return true;
};

/**
 * @method
 * @name checkIsuDtlDtl
 * @description 종목 상세(발행 내역) 입력값을 검증한다.
 * @param {*} dtsObj dtsObj
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.checkIsuDtlDtl = function (dtsObj) {
    if (dtsObj.getRowCount() === 0) {
        $c.win.alert("주식발행상세정보를 입력하세요.");
        return false;
    }
    for (j = 1; j <= dtsObj.getRowCount(); j++) {
        if (dtsObj.getCellData(j, "ISU_RND") === "") {
            $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별발행회차]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "isuDd") === "") {
            $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별발행일]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "ISU_PRC") === "") {
            // $c.win.alert("주식발행상세정보에서 "+ j+"행의 [개별발행가]를 입력하세요.");return false;

        }
        if (dtsObj.getCellData(j, "ISU_SHRS") === "") {
            $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별증감주식수]를 입력하세요.");
            return false;
        }
    }
    return true;
};

