/**
 * @method
 * @name getCheckboxNprefStk
 * @description 신형우선주여부 checkBox 데이터 세팅
 * @param {Object} obj 객체
 * @param {*} stk_knd stk_knd
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getCheckboxNprefStk = function (obj, stk_knd) {
    let val;
    if (obj.getValue() === "Y") {
        val = '2';
    } else {
        if (stk_knd === "000" || stk_knd === "KDR") {
            val = '0';
        } else {
            val = '1';
        }
    }
    return val;
};

