/**
 * @method
 * @name chkPrtdepoCond01
 * @description 상장방식-보호예수체크용코드있냐?
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.chkPrtdepoCond01 = function () {
    let vRsnCd = sbx_stkIsuRsnCd.getValue();
    if (vRsnCd === '141' || // DR분할
        vRsnCd === '142' || // DR병합
        vRsnCd === '170' || // 액면병합
        vRsnCd === '171' || // 액면분할
        vRsnCd === '172' || // 감자(주식병합)
        vRsnCd === '173' || // 회사분할(존속)
        vRsnCd === '174') {
        // 감자(주식소각)
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name chkPrtdepoCond02
 * @description 보호예수건수가있냐?
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.chkPrtdepoCond02 = function () {
    // if (dts_PRTDEPO.CountRow == 0) {
    if (scwin.gPrtdepoCount === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name chkPrtdepoCond03
 * @description 보호예수수정건수가있냐?
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.chkPrtdepoCond03 = function () {
    // let gPrtdepoCount = dts_PRTDEPO.CountRow;
    // $c.win.alert("gPrtdepoCount="+gPrtdepoCount);
    let gStat;
    let gStatCnt = 0;
    for (let k = 1; k <= dts_PRTDEPO.getRowCount(); k++) {
        gStat = dts_PRTDEPO.getRowStatus(k);
        // if (gStat == TB_JOB_UPDATE) {
        if (gStat === TB_JOB_NORMAL) {
            gStatCnt++;
        }
    }

    // $c.win.alert("gStatCnt="+gStatCnt);
    if (scwin.gPrtdepoCount === gStatCnt) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
        if (String(scwin.vBzProcsNo).length !== 14) {
            $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
        } else {
            dma_selectListRes.set("bzProcsNo", scwin.vBzProcsNo);

            if ((scwin.market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01()) {
                // $c.win.alert("test vBzProcsNo="+fn_chkPrtdepoCond_00() + fn_chkPrtdepoCond_01());

                if (scwin.chkPrtdepoCond) {
                    scwin.prtdepoReadSyncSTKCount();
                }
            }
            if ((scwin.market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01() && scwin.chkPrtdepoCond02() &&
                (scwin.gPrtdepoCount > 0) && scwin.chkPrtdepoCond) {

                $c.win.alert($c.data.getMessage("com_calc_0010"));
                scwin.prtdepoReadSyncSTK();
                scwin.chkPrtdepoCond = false;
                scwin.formCd = "68155";
                return;
            }
            if ((scwin.market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond03()) {
                let msg = "변경상장사유가 의무보유정보 수정대상이나 수정조치가 이루어지지 않았습니다.\n다시 한번 수정여부를 확인하여 주십시오.\n수정없이 그대로 진행하기를 원하시면 확인을 누르십시오.";
                let res = $c.win.confirm($c.data.getMessage("com_calc_0010"));
                if (!res) {
                    return;
                }
            }
            scwin.trs($c.lc.getGlbValue("TRS_IDX_INSERT"));
        }
    }
};

