/**
 * @method
 * @name isuDtlDtlAdd
 * @description 종목 상세(발행 내역) 행을 추가한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuDtlDtlAdd = function () {
    if (edt_INDVDL_ISU_RND.getValue() === "") {
        $c.win.alert("[개별발행회차]를 입력하세요.");
        edt_INDVDL_ISU_RND.focus();
        return;
    }
    if (edt_INDVDL_ISU_DD.getValue() === "") {
        $c.win.alert("[개별발행일]를 입력하세요.");
        edt_INDVDL_ISU_DD.focus();
        return;
    }
    if (edt_INDVDL_ISU_PRC.getValue() === "") {
        // $c.win.alert("[개별발행가]를 입력하세요.");edt_INDVDL_ISU_PRC.focus();return;

    }
    if (edt_INDVDL_INCDEC_LIST_SHRS.getValue() === "") {
        $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수]를 입력하세요.");
        edt_INDVDL_INCDEC_LIST_SHRS.focus();
        return;
    }
    let vRow = "";
    if (scwin.vIsuDtlRowPosition !== "") {
        vRow = scwin.vIsuDtlRowPosition;
    } else {
        dts_IsuDtl.insertRow();
        vRow = dts_IsuDtl.getRowCount();
    }

    // $c.win.alert('[ getObjectValue(edt_INDVDL_ISU_PRC)]'+ getObjectValue(edt_INDVDL_ISU_PRC));
    // $c.win.alert('[ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS)]'+ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS));
    dts_IsuDtl.setCellData(vRow, "ISU_RND", edt_INDVDL_ISU_RND.getValue());
    dts_IsuDtl.setCellData(vRow, "ISU_PRC", edt_INDVDL_ISU_PRC.getValue());
    dts_IsuDtl.setCellData(vRow, "ISU_SHRS", edt_INDVDL_INCDEC_LIST_SHRS.getValue());
    dts_IsuDtl.setCellData(vRow, "isuDd", edt_INDVDL_ISU_DD.getValue());
    dts_IsuDtl.setCellData(vRow, "PER1STK_CAP", edt_INDVDL_PER1STK_CAP.getValue());
    dts_IsuDtl.setCellData(vRow, "CORPBND_ISU_RND", edt_CORPBND_ISU_RND.getValue());
    if (dts_IsuDtl.getCellData(vRow, "PER1STK_CAP") > 0) {
        dts_IsuDtl.setCellData(vRow, "nparvalstkYn", "Y");
    }
    scwin.isuDtlDtlEvent();
};

/**
 * @method
 * @name isuDtlDtlDel
 * @description 종목 상세(발행 내역) 행을 삭제한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuDtlDtlDel = function () {
    if (dts_IsuDtl.getRowCount() === 0) {
        $c.win.alert("목록에서 [대상]을 선택하세요.");
        return;
    }
    dts_IsuDtl.removeRows(dts_IsuDtl.getRowPosition());
    scwin.isuDtlDtlEvent();
};

/**
 * @method
 * @name isuDtlDtlEvent
 * @description 종목 상세(발행 내역) 그리드 변경 이벤트 처리 — 합계·상태를 재계산한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuDtlDtlEvent = function () {
    edt_INDVDL_ISU_RND.setValue('');
    edt_INDVDL_ISU_PRC.setValue('');
    edt_INDVDL_INCDEC_LIST_SHRS.setValue('');
    edt_INDVDL_ISU_DD.setValue('');
    edt_INDVDL_PER1STK_CAP.setValue('');
    edt_CORPBND_ISU_RND.setValue('');
    scwin.isuPrcCalcuate();
    scwin.isuShrsCalcuate();
    scwin.vIsuDtlRowPosition = ""; // 초기화
};

/**
 * @method
 * @name isuPrcCalcuate
 * @description 발행가액을 계산한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuPrcCalcuate = function () {
    let vIsuPrcSum = 0;
    let vIsuRnd = "";
    let vIsuDd = "";
    try {
        if (dts_IsuDtl.getRowCount() > 0) {
            vIsuPrcSum = parseFloat(dts_IsuDtl.getCellData(1, "ISU_PRC"));
            vIsuRnd = dts_IsuDtl.getCellData(1, "ISU_RND");
            vIsuDd = dts_IsuDtl.getCellData(1, "isuDd");
            if (vIsuRnd === "") {
                vIsuRnd = ibx_isuRnd.getValue();
            }
        }
    } catch (err) {
        $c.win.alert("[개별발행가 계산중  오류]" + err);
    }
    // $c.stf.setObjectValue(edt_ISU_PRC, vIsuPrcSum);
    ibx_isuRnd.setValue(vIsuRnd);
    cal_isuDd.setValue(vIsuDd);
};

/**
 * @method
 * @name isuShrsCalcuate
 * @description 발행주식수를 계산한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuShrsCalcuate = function () {
    let vIsuShrsSum = 0;
    try {
        for (i = 1; i <= dts_IsuDtl.getRowCount(); i++) {
            vIsuShrsSum += parseInt(dts_IsuDtl.getCellData(i, "ISU_SHRS"));
        }
    } catch (err) {
        $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수 합산처리 중  오류]" + err);
    }
    ibx_isuShrs.setValue(vIsuShrsSum);
    scwin.calcuAccIsuShrs();
    scwin.calcusuCap();
    scwin.calcuAccIsuCap();
};

/**
 * @method
 * @name calcuAccIsuShrs
 * @description 변경후 상장주식수(주) 계산
 * @returns {void}
 * @hidden N
 */
scwin.calcuAccIsuShrs = function () {
    try {
        const bfAccIsuShrs = $c.util.isEmpty(ibx_bfAccIsuShrs.getValue()) ? 0 : ibx_bfAccIsuShrs.getValue();
        const isuShrs = $c.util.isEmpty(ibx_isuShrs.getValue()) ? 0 : ibx_isuShrs.getValue();
        let vsum = parseInt(bfAccIsuShrs) + parseInt(isuShrs);
        ibx_accIsuShrs.setValue(vsum);
    } catch (err) {
        $c.win.alert($c.data.getMessage("com_calc_0014", "변경후 상장증권수"));
    }
};

/**
 * @method
 * @name calcusuCap
 * @description 증감 상장자본금 계산
 * @returns {void}
 * @hidden N
 */
scwin.calcusuCap = function () {
    if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        ibx_isuCap.setValue(0);
    } else {
        try {
            let vRsnCd = sbx_stkIsuRsnCd.getValue();
            let vsum = 0;
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '171' || // 액면분할
                vRsnCd === '177') {
                // 주식소각
                vsum = 0; // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '641' || // 액면분할
                vRsnCd === '650') {
                // 주식소각
                vsum = 0; // 코스닥

            } else {
                const isuShrs = $c.util.isEmpty(ibx_isuShrs.getValue()) ? 0 : ibx_isuShrs.getValue();
                const per1stkCap = $c.util.isEmpty(ibx_per1stkCap.getValue()) ? 0 : ibx_per1stkCap.getValue();
                const parval = $c.util.isEmpty(ibx_parval.getValue()) ? 0 : ibx_parval.getValue();
                if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_MF") || scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_IF")) {
                    // vsum = parseFloat(edt_ISU_PRC.getValue()) * parseFloat(ibx_isuShrs.getValue());
                    vsum = parseFloat(isuShrs);
                } else {
                    if (cbx_nparvalstkYn.getValue() === "Y") {
                        vsum = parseFloat(per1stkCap) * parseFloat(isuShrs);
                    } else {
                        vsum = parseFloat(parval) * parseFloat(isuShrs);
                    }
                }
            }
            ibx_isuCap.setValue(vsum);
        } catch (err) {
            $c.win.alert($c.data.getMessage("com_calc_0014", "증감 상장자본금"));
        }
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description 변경후 상장자본금 계산
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuCap = async function () {
    if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        ibx_accIsuCap.setValue(0)
    } else {
        try {
            let vRsnCd = sbx_stkIsuRsnCd.getValue();
            let vsum = '';
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '177' || // 주식소각
                vRsnCd === '171') {
                // 액면분할
                vsum = ibx_bfAccIsuCap.getValue(); // 유가
                ibx_isuCap.setValue(0); // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '650' || // 주식소각
                vRsnCd === '641') {
                // 액면분할
                vsum = ibx_bfAccIsuCap.getValue(); // 코스닥
                ibx_isuCap.setValue(0); // 코스닥

            } else {
                const bfAccIsuCap = $c.util.isEmpty(ibx_bfAccIsuCap.getValue()) ? 0 : ibx_bfAccIsuCap.getValue();
                const isuCap = $c.util.isEmpty(ibx_isuCap.getValue()) ? 0 : ibx_isuCap.getValue();
                await scwin.calcusuCap();
                vsum = parseFloat(bfAccIsuCap) + parseFloat(isuCap);
            }
            ibx_accIsuCap.setValue(vsum);
        } catch (err) {
            $c.win.alert($c.data.getMessage("com_calc_0014", "변경후 상장자본금"));
        }
    }
};

/**
 * @method
 * @name setIsunNmComponent
 * @description 종목명 입력 컴포넌트 표시 상태를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setIsunNmComponent = function () {
    if (sbx_listMethdTpCd.getValue() === $c.lc.getGlbValue("LIST_METHD_TP_CD_1")) {
        ibx_isuKorNm.setReadOnly(false);
        ibx_isuKorAbbrv.setReadOnly(false);
        ibx_isuEngNm.setReadOnly(false);
        ibx_isuEngAbbrv.setReadOnly(false);
        ibx_isuEngSymbl.setReadOnly(false);
        ibx_isuKorNm.style.backgroundColor = '#ffffff';
        ibx_isuKorAbbrv.style.backgroundColor = '#ffffff';
        ibx_isuEngNm.style.backgroundColor = '#ffffff';
        ibx_isuEngAbbrv.style.backgroundColor = '#ffffff';
        ibx_isuEngSymbl.style.backgroundColor = '#ffffff';
    } else {
        ibx_isuKorNm.setReadOnly(true);
        ibx_isuKorAbbrv.setReadOnly(true);
        ibx_isuEngNm.setReadOnly(true);
        ibx_isuEngAbbrv.setReadOnly(true);
        ibx_isuEngSymbl.setReadOnly(true);
        ibx_isuKorNm.style.backgroundColor = '#b9d4f7';
        ibx_isuKorAbbrv.style.backgroundColor = '#b9d4f7';
        ibx_isuEngNm.style.backgroundColor = '#b9d4f7';
        ibx_isuEngAbbrv.style.backgroundColor = '#b9d4f7';
        ibx_isuEngSymbl.style.backgroundColor = '#b9d4f7';
    }
    if (scwin.vSpotIsuTrdMktTpCd === '1') {
        // $c.stf.showObj(panel_KSE, true);
        // panel_KSE_1.show();
        // panel_KSE_2.show();
        scwin.showSymbl(true);
    } else if (scwin.vSpotIsuTrdMktTpCd === '2' || scwin.vSpotIsuTrdMktTpCd === '6') {
        // $c.stf.showObj(panel_KSE, false);
        // panel_KSE_1.hide();
        // panel_KSE_2.hide();
        scwin.showSymbl(false);
    }
};

