/**
 * @method
 * @name getProvider
 * @description 자식생성창 에서 부모 프레임을 참조
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getProvider = function () {
    let url = frame.srcUrl;
    let arr = url.split("?");
    // $c.win.alert(url +"     =      "+ arr);
    // TODO Stage2: 프로젝트 공통 $c.frame 미반입(팝업/프레임 경로) — $c.win.openPopup/getParent 로 재설계
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentProvider
 * @description 부모 화면 객체를 구한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getParentProvider = function () {
    let url = $c.win.getParent().srcUrl;
    let arr = url.split("?");
    // $c.win.alert(url +"     =      "+ arr);
    // TODO Stage2: 프로젝트 공통 $c.frame 미반입(팝업/프레임 경로) — $c.win.openPopup/getParent 로 재설계
    return (arr.length >= 1 ? $c.frame.path("../../" + arr[1]) : undefined);
};

/**
 * @method
 * @name openDetailPrtdepo
 * @description 보호예수신규등록시
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailPrtdepo = async function (row) {
    if (row > -1) {
        // 그리드에서 선택시
        scwin.gPrtdepoSeq = row;
    } else {
        // 신규버튼 선택시
        scwin.gPrtdepoSeq = ""; // 초기화
    }

    // arrPar[0] = scwin.vSecugrpID;
    // arrPar[1] = ibx_isurCd.getValue(); // 코드값을 포함할 컨트롤

    const data = {
        isuKorNm: ibx_isuKorNm.getValue(),
        gPrtdepoSeq: scwin.gPrtdepoSeq,
        gDtsObj: dlt_prtdepoSelectListRes.getRowJSON(scwin.gPrtdepoSeq),
    };
    const opts = {
        id: "ULDSTF92025",
        popupName: "의무보유 등록/수정",
        width: 900,
        height: 650,
        frameModal: "top",
        type: "pageFramePopup",
    };
    const res = await $c.win.openPopup("/ui/lst/common/ULDSTF92025.xml", opts, data);
    if (res !== "") {
        dlt_prtdepoSelectListRes.insertRow(0);
        dlt_prtdepoSelectListRes.setRowJSON(0, res, true);
    }
};

