/**
 * @method
 * @name setPrestkEndDDEvent
 * @description 존속기한 입력
 * @returns {void}
 * @hidden N
 */
scwin.setPrestkEndDDEvent = function () {
    if (cbx_indefinpdYn.checked) {
        $c.win.alert("이미[무기한여부]가 선택되었습니다.\n\n만료일을 입력하시려면 무기한여부선택을 해제하시고 \n존속기한을 선택하십시요.");
        return;
    }
    if (cal_prefstkIsuDd.getValue() === "") {
        $c.win.alert("[우선주발행일]을 입력하세요.");
        cal_prefstkIsuDd.focus();
        return;
    }
    let vTgt;
    let vSrc = cal_prefstkIsuDd.getValue();
    vTgt = $c.date.addYear(vSrc, ibx_prefstkContinDeadlineYys.getValue());
    cal_prefstkEndDd.setValue(vTgt);
    vSrc = cal_prefstkEndDd.getValue();
    vTgt = $c.date.addMonth(vSrc.substring(0, 4), vSrc.substring(4, 6), vSrc.substring(6, 8), ibx_prefstkContinDeadlineMm.getValue());
    cal_prefstkEndDd.setValue(vTgt);
    vSrc = cal_prefstkEndDd.getValue();
    vTgt = $c.date.addDate(vSrc, ibx_prefstkContinDeadlineDys.getValue());
    cal_prefstkEndDd.setValue(vTgt);
};

