    } else {
        if (scwin.market === "2") {
            vMainFormCd = "70932";
        } else {
            vMainFormCd = "33032";
        }
    }
    let url = "/lstproc/ULDSTF05014.xml?ISUR_CD=" + ibx_isurCd.getValue() + "&ACPT_NO=" + scwin.gAcptNoListFee + "&FORM_CD=" + vMainFormCd;
