    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};

/**
 * @method
 * @name showSymbl
 * @description 종목심볼 보여주기
 * @param {String} gubun 구분 값
 * @returns {void}
 * @hidden N
 */
scwin.showSymbl = function (gubun) {
    if (gubun) {
        lb_ISU_ENG_SYMBL.setValue("종목심볼");
        ibx_isuEngSymbl.show();
        btn_isuEngSymbl.show();
    } else {
        lb_ISU_ENG_SYMBL.setValue("");
        ibx_isuEngSymbl.hide();
        btn_isuEngSymbl.hide();
    }
}
